export const getDownloadGenerationUrl = (id: number,
    params?: DownloadGenerationParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/generations/${id}/download?${stringifiedParams}` : `/api/generations/${id}/download`
}

/**
 * scope=package downloads only the generated design system files. scope=codebase re-fetches the imported repository and injects the generated files into it (repo-sourced projects only).
 * @summary Download the generation as a zip
 */
export const downloadGeneration = async (id: number,
    params?: DownloadGenerationParams, options?: RequestInit): Promise<Blob> => {

  return customFetch<Blob>(getDownloadGenerationUrl(id,params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getDownloadGenerationQueryKey = (id: number,
    params?: DownloadGenerationParams,) => {
    return [
    `/api/generations/${id}/download`, ...(params ? [params] : [])
    ] as const;
    }


export const getDownloadGenerationQueryOptions = <TData = Awaited<ReturnType<typeof downloadGeneration>>, TError = ErrorType<ErrorResponse>>(id: number,
    params?: DownloadGenerationParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof downloadGeneration>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getDownloadGenerationQueryKey(id,params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof downloadGeneration>>> = ({ signal }) => downloadGeneration(id,params, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: id !== null && id !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof downloadGeneration>>, TError, TData> & { queryKey: QueryKey }
}

export type DownloadGenerationQueryResult = NonNullable<Awaited<ReturnType<typeof downloadGeneration>>>
export type DownloadGenerationQueryError = ErrorType<ErrorResponse>


/**
 * @summary Download the generation as a zip
 */

export function useDownloadGeneration<TData = Awaited<ReturnType<typeof downloadGeneration>>, TError = ErrorType<ErrorResponse>>(
 id: number,
    params?: DownloadGenerationParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof downloadGeneration>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getDownloadGenerationQueryOptions(id,params,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







